const id=new URLSearchParams(location.search).get("id");
const node=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;};
(async()=>{try{const response=await fetch(`api/reviews/${encodeURIComponent(id)}`);if(!response.ok)throw Error(`Review fetch failed (${response.status})`);const record=await response.json(), collection=record.collection;
document.getElementById("title").textContent=record.source_id;
const provenance=collection.execution_provenance;document.getElementById("provenance").textContent=`Review date ${collection.reviews.map(review=>review.reviewed_at).filter(Boolean).sort().at(-1) || "unknown"} · Imported ${collection.created_at} · MSkyRL SHA: ${provenance?.marinskyrl_commit || "Unknown (imported review)"}${provenance?.marinskyrl_dirty ? " · working tree has edits; recorded code digest applies" : ""}`;
const difficultyArtifact=record.artifacts.find(item=>item.path==="difficulty.json");
if(difficultyArtifact){const url=`api/reviews/${encodeURIComponent(id)}/artifacts/difficulty.json`;const response=await fetch(url);if(!response.ok)throw Error(`Difficulty fetch failed (${response.status})`);const report=await response.json();const card=node("section");card.className="review-card";card.append(node("h2","Paired difficulty estimate"),node("p",`${report.sampling.task_count} shared tasks · ${report.sampling.method} · split ${report.split}`));for(const model of report.models)card.append(node("p",`${model.size}: ${model.model} · ${model.solved}/${model.verified} solved (${(100*model.solve_rate).toFixed(1)}%) · 95% interval ${(100*model.wilson_95[0]).toFixed(1)}–${(100*model.wilson_95[1]).toFixed(1)}%`));for(const limitation of report.limitations)card.append(node("p",limitation));const link=node("a","Download difficulty JSON and per-task outcomes");link.href=url;card.append(link);document.getElementById("reviews").append(card);}
for(const mapping of collection.source_mappings)document.getElementById("reviews").append(node("p",`Revision applicability: ${mapping.applicability}. ${mapping.note || ""}`));
for(const review of collection.reviews){const card=node("section");card.className="review-card";card.append(node("h2",`${review.reviewer.label}: ${review.verdict}`),node("p",`${review.method} · ${review.subject_id}`),node("p",review.summary));for(const metric of review.metrics)card.append(node("p",`${metric.key}: ${metric.value}`));for(const finding of review.findings)card.append(node("p",`${finding.severity || "Unrated"} · ${finding.dimension}: ${finding.text}`));for(const evidence of review.evidence){const anchor=node("a",evidence.snapshot_path);anchor.href=evidence.url.startsWith("file:") ? `api/reviews/${encodeURIComponent(id)}/artifacts/${evidence.snapshot_path.split("/").map(encodeURIComponent).join("/")}` : evidence.url;anchor.target="_blank";anchor.rel="noopener";const paragraph=node("p");paragraph.append(anchor);card.append(paragraph);}document.getElementById("reviews").append(card);}
document.getElementById("download").addEventListener("click",()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(collection,null,2)],{type:"application/json"}));const a=node("a");a.href=url;a.download=`${id}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
}catch(error){document.getElementById("title").textContent=error.message;}})();
